definition.raw:
For $x_i \in \Sigma$ the map $q \circ u_i : \mathbb{S}^1 \times [0, 1] \to E$ restricted to $\mathbb{S}^1 \times \left\{ 1 \right\}$ gives a map $\gamma_i : \mathbb{S}^1 \to F_{x_i}$, and therefore an element $ind_{x_i}(s) \in \pi_1(F)$ via the isomorphism $\pi_1(\eta_x)$ (see~\eqref{eq:8}).
This element $ind_{x_i}(s)$ will be called the \emph{index of the section $s$ at the point $x_i \in \Sigma$}.
\label{df:1}

For $a \in H^1(F)$ we define the \emph{index $ind_{x_i}(s;a)$ of the section $s$ at the point $x_i \in \Sigma$ with respect to $a$} as
\begin{equation}
ind_{x_i}(s;a) = \langle a, ind_{x_i}(s) \rangle = \int_\gamma \alpha = \int_{\mathbb{S}^1} \gamma^* \alpha,
\label{eq:11}
\end{equation}
where $\gamma : \mathbb{S}^1 \to F$ is the curve representing the element $ind_{x_i}(s) \in \pi_1(F)$ and $\alpha \in \Omega^1(F)$ is a closed form representing the element $a \in H^1(F)$.
\emph{The index of a section $s$ with respect to $a$} is the number
\begin{equation}
ind(s; a) = \sum_{x_i \in \Sigma} ind_{x_i}(s;a).
\label{eq:12}
\end{equation}
\label{df:2}

A \emph{projective bundle} is a locally trivial bundle $Q \to M$ with typical fiber $\mathbb{R}P^n$ and structure group $PGL(n)$.
The number $n$ is called the \emph{rank} of $Q$.
\label{df:3}

Let $Q \to M$ be a projective bundle of rank $n$.
The principal bundle $PGL(Q)$ with the group $PGL(n)$ adjoint to $Q$ is called the \emph{bundle of projective frames}.
\label{df:4}

theorem.raw:
\emph{a)} $\pi \circ q : S \setminus \partial S \to M \setminus \Sigma$ is a diffeomorphism.

\emph{b)} The map $\pi \circ q : S \to M$ is surjective.

\emph{c)} $\pi \circ q(\partial S) = \Sigma$.

\emph{d)} Let $\partial S = \bigcup\limits_{i = \overline{1, k}} \partial S_i$, where $\partial S_i$ are the boundary components.
Then for any $x \in \Sigma$, there exist one and only one boundary component $\partial S_i$ such that $\pi^{-1}(x) = q(\partial S_i)$.

\emph{e)} For any $x \in \Sigma$ exists a neighborhood $U$ of $x$ such that
\begin{enumerate}
\item
$U$ is diffeomorphic to a disk;
\item
There exists a closed set $V \subset S$ diffeomorphic to a ring such that the boundary of $V$ consists of two connected components $C$ and $C'$, where the connected component $C$ is a closed curve in $S \setminus \partial S$ and the other connected component $C'$ is the connected component $\partial S_i$ of the boundary $\partial S$ which corresponds to $x$ by d), and
\begin{equation}
\pi \circ q(C) = \partial U, \quad \pi \circ q(V \setminus \partial V) = U \setminus x, \quad \pi \circ q(\partial S_i) = x
\label{eq:4}
\end{equation}
\end{enumerate}

\label{thm:1}

For $a \in H^1(F)$, let $\alpha \in \Omega^1(E)$ be the corresponding vertical form constructed in Statement~\ref{stat:1}.
Also let $d\alpha = \theta_{(1, 1)} + \theta_{(2, 0)}$ as in Statement~\ref{stat:5}.
Then
\begin{equation}
\int\limits_S q^*\theta_{(1, 1)} + q^*\alpha(\Omega) = \sum\limits_{i = \overline{1, k}} index_{x_i}(s; a).
\label{eq:33}
\end{equation}
\label{thm:2}

Let $\omega_E: TE \rightarrow VE$ be a connection form induced by a connection in the principal $\bar{G}$-bundle $\bar{P} \to M$ (see~Statement~\ref{stat:11}). 

Then
\begin{equation}
\alpha(X)=\tilde{\alpha}(\omega_E(X))
\label{eq:81}
\end{equation}
The form $\alpha$ given by~\eqref{eq:81} satisfies the properties (1) and (2) of Statement~\ref{stat:1}.
\label{thm:4}

Let $M$ be a compact connected two-dimensional manifold, let $E_i\rightarrow M, \ i=1, \cdots, k$, are $k$ vector bundles of rank $2$ over $M$, let $\tilde{E}_i =E_i\setminus s^0_i(M)$, where $s^0_i: M\rightarrow E_i$ is the zero section of $E_i$, and let $s_i : M \rightarrow E_i$ be a section of $E_i$ for each $i$.
If $\omega_1, \cdots, \omega_k$ are connections on $E_1, \cdots, E_k$ respectively, $K_1, \cdots, K_k$ are the curvatures of these connections, and $s = (s_1, \cdots, s_k) : M\setminus \Sigma \rightarrow \tilde{E}$, then
\begin{equation}
\sum_{j=\overline{1, k}}\int_M K_i \theta = \sum_{x_i \in \Sigma} \sum_{j=\overline{1, k}}ind_{x_i}(s_j, [d\phi_j]),
\label{eq:89}
\end{equation}
where $d\phi_i\in \Omega^{1}(\mathbb{R}^{2})$ is the angular form of $\mathbb{R}^{2}$, and $\theta$ is the area form on $M$.
\label{thm:5}

lemma.raw:
\begin{equation}
d(Dy^a) = \Gamma_i{ }^a_b Dy^b \wedge dx^i + R_{ij}{ }^a_b y^b dx^i \wedge dx^j,
\label{eq:65}
\end{equation}
where $R_{ij}{ }^a_b = \partial_i \Gamma_j{ }^a_b - \partial_j \Gamma_i{ }^a_b + \Gamma_i{ }^a_c \Gamma_j{}^c_b - \Gamma_j{ }^a_c \Gamma_i{}^c_b$ is the curvature tensor of the linear connection in $E$.
\label{lm:2}

a) $\widetilde{\omega}$ is a field of projectors onto the vertical distribution $\bar{V}$ with kernel $\bar{H}$.

b) $\widetilde{\omega}_{\bar{p}\bar{g}} \circ dR_{\bar{g}} (\bar{X}) = dR_{\bar{g}} \circ \widetilde{\omega}_{\bar{p}} (\bar{X})$, where $R_{\bar{g}} : \bar{G} \to \bar{G}$, $R_{\bar{g}} \bar{g}' = \bar{g}' \bar{g}$.

\label{lm:3}

corollary.raw:
Let $E \to M$ be a vector bundle and $Q = P(E)$.
Assume that $g$ is a metric in $E$.
Let $\Omega$ be the curvature form of the connection in $Q$ induced by a connection in $E$ adapted to $g$.
Let $a \in H^1(\mathbb{R}P^1)$ is represented by the form $\bar \alpha$.
If $s : M \setminus \Sigma \to Q$ is a section with singularities,
\begin{equation}
ind (s; a) = \int_M \Omega.
\label{eq:73}
\end{equation}
\label{cor:3}

Let $\bar{P}(M, \bar{G}, \pi)$ a principal $G$-bundle with singularities, and let $\Sigma$ be the set of singularities.
Then there is a section $s: M\setminus \Sigma \rightarrow \bar{P}/G$.
\label{cor:4}

proof.raw:
Let us take an atlas $(U_i, \psi_i)$ of the bundle $\xi$, and fix a $1$-form $\bar\alpha \in \Omega^1(F)$ such that $[\bar\alpha] = a$.
Let $\rho_i$ be the partition of unity subordinate to the covering $\left\{ U_i \right\}$, and $\eta_i : \pi^{-1}(U_i) \to F$ (see~\eqref{eq:6}).
Then take the collection of $1$-forms $\bar\alpha_i = \eta^*_i \bar\alpha \in \Omega^1(\pi^{-1}(U_i))$, and then construct $\widetilde{\alpha} = \sum_i \pi^*\rho_i\, \bar\alpha_i \in \Omega^1(V)$.
Then
\begin{equation}
i_x^* \widetilde{\alpha} = \sum_i \rho_i(x)\, i_x^* \bar\alpha_i = \sum_i \rho_i(x)\, i_x^* \eta_i^* \bar\alpha \in \Omega^1(F_x).
\label{eq:14}
\end{equation}
Therefore,
\begin{equation}
d i_x^* \widetilde{\alpha} = \sum_i \rho_i(x)\, i_x^* \eta_i^* d\bar\alpha = 0
\label{eq:15}
\end{equation}
and
\begin{equation}
[ i_x^* \widetilde{\alpha} ] = \sum_i \rho_i(x)\, [ i_x^* \eta_i^* \bar\alpha ] = a,
\label{eq:16}
\end{equation}
because $\sum_i \rho_i(x) = 1$.
We have the decomposition $TE = H \oplus V$, and therefore we can define the desired $\alpha \in \Omega^1(E)$ by
$\left.\alpha\right|_H = 0$ and $\left.\alpha\right|_{V} = \widetilde{\alpha}$.

Let $\left\{ e_\alpha \right\}$ be a local frame field of $\xi$, and $\omega = \omega^\alpha e_\alpha$.
Then
\begin{equation}
\nabla_X (\omega(Y) ) = \nabla_X (\omega^\alpha(Y) e_\alpha ) = X(\omega^\alpha(Y)) e_\alpha + \omega^\alpha(Y) \nabla_X e_\alpha,
\label{eq:23}
\end{equation}
therefore
\begin{multline}
\nabla_X (\omega(Y)) - \nabla_Y (\omega(X)) - \omega([X, Y]) =
\\
X(\omega^\alpha(Y)) e_\alpha + \omega^\alpha(Y) \nabla_X e_\alpha - Y(\omega^\alpha(X)) e_\alpha - \omega^\alpha(X) \nabla_Y e_\alpha - \omega^\alpha([X, Y]) e_\alpha =
\\
d\omega^\alpha(X, Y) e_\alpha - \omega^\alpha \wedge \nabla e_\alpha (X, Y) = D\omega (X, Y).
\label{eq:24}
\end{multline}

It is sufficient to prove that $D\omega(X, Y) = 0$ if $Y \in \mathfrak{X}^v(E)$.
We will apply~\eqref{eq:22}.
If $X \in \mathfrak{X}^h(E)$, then
\begin{equation}
D\omega(X, Y) = \nabla_X \omega(Y) - \nabla_Y \omega(X) - \omega( [X, Y] ) = \nabla_X Y - \omega( [X, Y] ) = 0
\label{eq:26}
\end{equation}
by the definition of $\nabla$ (see~\eqref{eq:18} and~\eqref{eq:19}).
If $X \in \mathfrak{X}^v(E)$, then
\begin{equation}
D\omega(X, Y) = \nabla_X \omega(Y) - \nabla_Y \omega(X) - \omega( [X, Y] ) = 0
\label{eq:27}
\end{equation}
again by the definition of $\nabla$ and because the connection $\nabla^V$ is torsion free.

Indeed, by Statement~\ref{stat:3}, we have that, for any horizontal vector fields $X$ and $Y$,
\begin{equation}
D\omega(X, Y) = - \omega([X, Y]),
\label{eq:28}
\end{equation}
therefore $D\omega(X^h, Y^h) = 0$, for any $X^h$ and $Y^h$ if and only if the Lie bracket of horizontal vector fields is again a horizontal vector field, this is equivalent to integrability of $H$.

By the Stokes theorem,
\begin{equation}
\int_S d q^* \alpha = \int_{\partial S} q^*\alpha = \sum\limits_{i=1}^k \int_{\partial S_i} q^*\alpha.
\label{eq:34}
\end{equation}
We have that
\begin{equation}
\int_{\partial S_i} q^*\alpha = \int_{\mathbb{S}^1 \times \{ 1 \}} u_i^* q^* \alpha = \int_{\mathbb{S}^1} \gamma_i^* \alpha = \int_{\gamma_i} \alpha = ind_{x_i}(s; a),
\label{eq:35}
\end{equation}
Therefore,
\begin{equation}
\sum\limits_{i=1}^k \int_{\partial S_i} q^*\alpha = ind_{x_i}(s; a).
\label{eq:36}
\end{equation}
On the other hand, by Statement~\ref{stat:5},
\begin{equation}
\int_S d q^* \alpha = \int_S q^* d\alpha = \int_S q^*\theta_{(1, 1)} + q^*\theta_{(2, 0)}.
\label{eq:37}
\end{equation}
and thus we get the required statement.

Let us prove that $\left\{ z_{ijk} \right\}$ is a \v Chech cocycle on $\mathcal{U}$.
First of all note that we have
\begin{equation}
\widetilde{g}_{ij} \widetilde{g}_{jk} = z_{ijk} \widetilde{g}_{ik} = \widetilde{g}_{ik} z_{ijk}.
\label{eq:51}
\end{equation}
Then
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) \widetilde{g}_{ki} = z_{ijk} \widetilde{g}_{ik} \widetilde{g}_{ki} = z_{ijk} \text{ and } \widetilde{g}_{ij} (\widetilde{g}_{jk} \widetilde{g}_{ki}) = \widetilde{g}_{ij} \widetilde{g}_{ji} z_{jki} = z_{jki},
\label{eq:52}
\end{equation}
therefore $z_{ijk} = z_{kij} = z_{jki}$.
At the same time,
\begin{equation}
z_{ijk}^{-1} \widetilde{g}_{ik}^{-1} = \left( z_{ijk} \widetilde{g}_{ik} \right)^{-1} = \left( \widetilde{g}_{ij} \widetilde{g}_{jk} \right)^{-1} = \widetilde{g}_{kj} \widetilde{g}_{ji} = z_{kji} \widetilde{g}_{ki},
\label{eq:53}
\end{equation}
hence follows that $z_{ijk}^{-1} = z_{kji} = z_{jik}$.
Moreover $z_{ijk} = 1$ if at least two indices coincide.
Thus $z = \left\{ z_{ijk} \right\}$ is a normalized cochain.
Now we have
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) (\widetilde{g}_{kj} \widetilde{g}_{jl}) = z_{ijk} \widetilde{g}_{ik} z_{kjl} \widetilde{g}_{kl} = z_{ijk} z_{kjl} z_{ikl} g_{il}
\label{eq:54}
\end{equation}
and
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) (\widetilde{g}_{kj} \widetilde{g}_{jl}) = (\widetilde{g}_{ij} (\widetilde{g}_{jk} (\widetilde{g}_{kj}) \widetilde{g}_{jl} = \widetilde{g}_{ij} \widetilde{g}_{jl} = z_{ijl} \widetilde{g}_{il},
\label{eq:55}
\end{equation}
thus $z_{ijk} z_{kjl} z_{ikl} = z_{ijl}$, this implies
\begin{equation}
\delta z = z_{jkl} z_{ikl}^{-1} z_{ijl} z_{ijk}^{-1} = 0.
\label{eq:56}
\end{equation}
If $z = \delta u$, where $u = \left\{ u_{ij} \in Z \right\}$, then
\begin{equation}
z_{ijk} = u_{ij} u_{jk} u_{ki}.
\label{eq:57}
\end{equation}
Therefore we can construct the $\widetilde{G}$-principal bundle $\widetilde{P} \to M$ with the transition functions $\widetilde{g}'_{ij} = \widetilde{g}_{ij} u_{ji}$ because
\begin{equation}
\widetilde{g}'_{ij} \widetilde{g}'_{jk} \widetilde{g}'_{ki} =\widetilde{g}_{ij} u_{ji} \widetilde{g}_{jk} u_{kj} \widetilde{g}_{ki} u_{ik} =\widetilde{g}_{ij} \widetilde{g}_{jk} \widetilde{g}_{ki} u_{ji} u_{kj} u_{ik} =
z_{ijk} u_{ji} u_{kj} u_{ik} = 1.
\label{eq:58}
\end{equation}
Now we have that $p(\widetilde{g}'_{ij}) = g_{ij}$ and from the following lemma it follows that there exists a principal bundle morphism $\pi : \widetilde{P} \to P$ written with respect to the trivializations as $(x, \widetilde{g}) \to (x, p(\widetilde{g}))$.
\begin{lm}
Let $G_a$, $a = 1, 2$ be Lie groups.
Let $\pi_a : P_a \to M$, $a = 1, 2$ be a $G_a$-principal bundle and $f : G_1 \to G_2$ be a Lie group homomorphism.
Assume that $\mathcal{U} = \left\{ U_i \right\}$ is a trivializing covering for $P_1$ and $P_2$ at the same time.
If the transition functions $g^a_{ij}$ with respect to the covering $\mathcal{U}$ are related by $f(g^1_{ij}) = g^2_{ij}$, then there exists a principal fiber bundle homomorphism $F : P_1 \to P_2$ corresponding to $f$, i.\, e. $F(p_1 g_1) = F(p_1) f(g_1)$.
\label{lm:1}
\end{lm}
\begin{proof}
We define $F_i : \pi_1^{-1}(U_i) \to \pi_2^{-1}(U_i)$ by the commutative diagram
\begin{equation}
\xymatrix{
\pi_1^{-1}(U_i) \ar[r]^{F_i} \ar[d]_{\psi_i^1} & \pi_2^{-1}(U_i) \ar[d]^{\psi_i^2}
\\
U_i \times G_1 \ar[r]^{ 1 \times f} & U_i \times G_2
}
\label{eq:59}
\end{equation}
where $\psi_a$ are the trivializations which are principal bundle isomorphisms, therefore $\psi_a(p_a g_a) = \psi_a(p_a) g_a$, where the action of $G_a$ on $U_i \times G_a$ is given by $(x, g_a) g'_a = (x, g_a g'_a)$.
From this follows that $F_i(p_1 g_1) = F_i(p_1) g_1$.
On the other hand, for $p_1 \in \pi^{-1}(U_{ij})$ we have $F_i(p_1) = F_j(p_1)$.
Indeed, we have the commutative diagram for $a = 1, 2$:
\begin{equation}
\xymatrix{
U_{ij} \times G_a{}\ar[rr]^{(x, g_a) \to (x, g^a_{ji} g_a)} & & U_{ij} \times G_a
\\
&\pi_1^{-1}(U_{ij}) \ar[lu]^{\psi^a_i} \ar[ru]_{\psi^a_j} &
}
\label{eq:60}
\end{equation}
Let $p_1 \in \pi^{-1}(U_{ij})$ and $\psi^1_i(p_1) = (x, g_1)$, then $\psi^1_j(p_1) = (x, g^1_{ji} g_1)$.
Also $\psi^2_i F_i(p_1) = (x, f(g_1))$, hence $\psi^2_j F_i(p_1) = (x, g^2_{ji} f(g_1))$.
Therefore,
\begin{equation}
\psi^2_j F_j(p_1) = (x, f(g^1_{ji} g_1)) = (x, f(g^1_{ji}) f(g_1))
= (x, g^2_{ji} f(g_1)) = \psi^2_j F_i(p_1),
\label{eq:61}
\end{equation}
thus $F_j = F_i$ on $\pi^{-1}(U_{ij})$ and therefore $\left\{ F_i \right\}$ determine a homomorphism $F : P_1 \to P_2$.

The isomorphism $V_E \cong \bar{P}\times_{\bar{G}} \bar{G} \times \bar{\mathfrak{g}}/\mathfrak{g} \cong \bar{P}\times_G \mathfrak{m}$ follows from the fact that $VE=\bar{P}\times_{\bar{G}} T(\bar{G}/G)$~\cite{michor2000}(Chapter IV, section 18.18)
and that $T(\bar{G}/G)=\bar{G}\times \bar {\mathfrak{g}} / \mathfrak{g}$~\cite{sharpe2000}(Chapter 4, section 5).
In the exact form the isomorphism is written as follows:
\begin{equation}
\bar{P}\times_G \mathfrak{m} \to VE, \quad [\bar{p}, a] \mapsto d\pi_G(\sigma_{\bar{p}} (a)).
\label{eq:79}
\end{equation}

For $X \in H$, $\omega_E(X) = 0$, therefore $\alpha(X) = 0$.

Recall that the trivializations of $E = P/G$ are constructed in the following way.
For a good covering $U_i$ of $M$ we take sections $s_i : U_i \to P$, then we define the charts
\begin{equation}
\psi_i : U_i \times \bar{G}/G \to \pi_E^{-1}(U_i), \quad (x, [\bar{g}]) \to [s_i(x) \bar{g}] = \pi_G(s_i(x) \bar{g}).
\label{eq:82}
\end{equation}
Therefore, for $x \in U_i$, $\eta_x^{-1} : \bar{G}/G \to E_x = \pi_E^{-1}(x)$, $\eta_x^{-1}[\bar{g}] = \pi_G(s_i(x)\bar{g})$.

Now let us fix $x \in U_i \subset M$ and let $\bar{p} = s_i(x)$.
For any $y \in E_x$ and $Y \in V_yE$, we have that $y = \pi_G(\bar{p} \bar{g}) = [\bar{p}, \bar{g}] = \eta_x^{-1}(\bar{g})$ and $Y = d\pi_G(\sigma_{\bar{p} \bar{g}}(a)) = [\bar{p} \bar{g}, a] = d\eta_x^{-1} (dL_{\bar{g}} a)$, where $a \in \mathfrak{m}$, and $L_{\bar{g}} : \bar{G}/G \to \bar{G}/G$, $L_{\bar{g}} \bar{g}' = \bar{g}\bar{g}'$.
Note that here we use the isomorphism constructed in Lemma~\ref{lm:4}. 
Then
\begin{equation}
\alpha(Y) = \widetilde{\alpha}(\omega_E(Y)) = \widetilde{\alpha}(Y) = \xi_0(a) = \xi(dL_{\bar{g}} a).
\label{eq:83}
\end{equation}
Therefore $\alpha(d\eta_x^{-1} (dL_{\bar{g}} a) ) = \xi(dL_{\bar{g}} a)$, thus $(\eta_x^{-1})^* \left.\alpha\right|_{E_x} = \xi$, then $\eta_x^* \xi = \left.\alpha\right|_{E_x}$.

Thus $d\left(\left.\alpha\right|_{E_x} \right) = 0$, and $\left[\left.\alpha\right|_{E_x} \right] = H^1(\eta_x) a$.

Let $S$ be an oriented $2$-manifold with boundary, and let $q: S \rightarrow E$ a map which satisfies the condition given in section~\ref{sec:1}, that is, $q_i$ restricted to $\overset{\circ}{S} = S \setminus \partial S$ is a diffeomorphism between $S \setminus \partial S$ and $s_i(M \setminus \Sigma)$.
Now, because $E=\tilde{E}_1 \times \cdots \tilde{E}_k$, $q$ has the form $q=(q_1, \cdots, q_k)$, and for each $i$, the map $q_i: S\rightarrow \tilde{E}_i$ also satisfies this condition.
This fact follows from the commutative diagram
\begin{equation}
\xymatrix{
& M\setminus \Sigma \ar[r]^{id} \ar[d]_{s} & M\setminus \Sigma \ar[d]^{s_i}\\
\overset{\circ}{S}\ar[r]^{q} & s(M\setminus \Sigma)\ar[r]^{\tilde{p}_i} & s_i(M\setminus \Sigma)
}
\label{eq:90}
\end{equation}
Since the vertical arrows are diffeomorphisms, we have that $q_i$ is a diffeomorphism.
Therefore, for each $i = 1,\cdots, k$, the map $q_i=\tilde{p}_i\circ q$ is also a diffeomorphism.


Let us take the cohomology class $a=[(d\phi_1, \cdots, d\phi_k)]$ of the fiber of $\tilde{E}$, where $d\phi_i$ is the angular form on the fiber $F_i$ of $E_i$, then $a=[d\phi_1]+ \cdots +[d\phi_k]$.
Thus, the expression at the right side of equation~\eqref{eq:86} can be written as follows
\begin{equation}
\sum_{x_i \in \Sigma} index_{x_i}(s,a)=\sum_{x_i \in \Sigma} \sum_{j=\overline{1, k}}ind_{x_i}(s_j, [d\phi_j]).
\label{eq:91}
\end{equation}
Furthermore, $d\overset{i}{G}=K_i \theta$, and $d\alpha =\sum_{j=\overline{1, k}} \pi^{*}(K_i \theta)$.
Therefore, the expression at the left side of equation~\eqref{eq:86} reduces to the following equality
\begin{equation}
\int_S q^{*}\pi^{*}dG=\sum_{j=\overline{1, k}}\int_M K_i \theta
\label{eq:92}
\end{equation}
Hence, we obtain the following equation
\begin{equation}
\sum_{i=\overline{1, k}}\int_M K_i \theta = \sum_{x_i \in \Sigma} \sum_{j=\overline{1, k}}ind_{x_i}(s_j, [d\phi_j]).
\label{eq:93}
\end{equation}

remark.raw:
From the proof of items d) and e) of Theorem~\ref{thm:1} it follows that, for each boundary component $\partial S_i$, we have a closed neighborhood $V_i$ of $\partial S_i$ and a diffeomorphism of manifolds with boundary $u_i : \mathbb{S}^1 \times [0, 1] \to V_i$ such that $u_i(\mathbb{S}^1 \times \left\{ 1 \right\} = \partial S_i$, $U = \pi \circ q \circ u_i(\mathbb{S}^1 \times [0, 1])$ is a closed neighborhood of $x_i \in \Sigma$ diffeomorphic to a disk, $\pi \circ q \circ u_i(\mathbb{S}^1 \times \left\{ 0 \right\}$ is the boundary of $U$, and $\pi \circ q \circ u_i(\mathbb{S}^1 \times \left\{ 1 \right\} = x$ (see Figure~\ref{fig:1}).
\begin{figure}[h]
\centering
\includegraphics[scale=0.1]{fig1.pdf}
\caption{The surface $S$}
\label{fig:1}
\end{figure}
\label{rem:2}

By~\eqref{eq:11},
\begin{equation}
ind_{x_i}(s;a) = \int_{\gamma_i} \eta_x^*\alpha,
\label{eq:13}
\end{equation}
where $[\alpha] = a$ and $\gamma_i$ is defined in Definition~\ref{df:1}.
\label{rem:4}

The bundle $E \to M$ is the bundle associated with the principal $\bar{G}$-bundle $\bar{P} \to M$ with the fiber $\bar{G}/G$ with respect to the left action of $\bar{G}$ on $\bar{G}/G$.
The distribution $HE$ is the connection induced on the associated bundle by the connection $\bar{H}$ on $\bar{P}$.
\label{rem:9}

example.raw:
Let $\xi$ be a unit vector bundle of $\mathbb{R}^2$, $\pi : \mathbb{R}^2 \times \mathbb{S}^1 \to \mathbb{R}^2$, and consider a section $s : \mathbb{R}^2 \to E$ which takes value $s(\rho, \varphi) = (\cos n\varphi, \sin n\varphi)$ with respect to the polar coordinate system on $\mathbb{R}^2 \setminus (0, 0)$.
