\psi^2_j F_j(p_1) = (x, f(g^1_{ji} g_1)) = (x, f(g^1_{ji}) f(g_1))
= (x, g^2_{ji} f(g_1)) = \psi^2_j F_i(p_1),
\label{eq:61}
\end{equation}
thus $F_j = F_i$ on $\pi^{-1}(U_{ij})$ and therefore $\left\{ F_i \right\}$ determine a homomorphism $F : P_1 \to P_2$.
\end{proof}
From the construction of the bundle $\widetilde{P}$ it follows that $P = \widetilde{P}/Z$ and the principal fiber bundle homomorphism constructed in Lemma~\ref{lm:2} is exactly the projection $\widetilde{P} \to P=\widetilde{P}/Z$.
\end{proof}
Let $Q$ be a projective bundle of rank $n$, $n$ is odd.
Assume that $Q$ is orientable.
Let $\left\{ U_i \right\}$ be a good covering of $M$, $U_{i_1 \ldots i_k} = U_{i_1} \bigcap \cdots \bigcap U_{i_k}$, and $g_{ij} : U_{ij} \to PGL(n)$ the corresponding cocycle of transition functions.
As $U_{ij}$ are contractible, we can choose the maps $\hat{g}_{ij} : U_{ij} \to SL(n + 1)$ such that $p(\hat{g}_{ij}) = g_{ij}$, where $p : SL(n + 1) \to PGL_{+}(n)$ is the canonical projection.
Then $p(\hat{g}_{ij} \hat{g}_{jk} \hat{g}_{ki}) = g_{ij} g_{jk} g_{ki} = id \in PGL(n)$, therefore $e_{ijk} = \hat{g}_{ij} \hat{g}_{jk} \hat{g}_{ki}$ takes values in $\mathbb{Z}_2 = \left\{ \pm I \right\}$.
Note that $\mathbb{Z}_2 = \left\{ \pm I \right\}$ is the center of the group $SL(n + 1)$.
\begin{cor}
If $Q \to M$ is a projective bundle of odd rank $n$ and is oriented, then the obstruction to existence of a vector bundle $E$ such that $Q = P(E)$ is an element in $H^2(M, \mathbb{Z}_2)$.
\label{cor:2}
\end{cor}
\begin{df}
Let $Q \to M$ be a projective bundle of rank $n$.
The principal bundle $PGL(Q)$ with the group $PGL(n)$ adjoint to $Q$ is called the \emph{bundle of projective frames}.
\label{df:4}
\end{df}
\begin{ex}
On the total space of a vector bundle $E \to M$ the group $\mathbb{R}^{*} = \mathbb{R} \setminus \left\{ 0 \right\}$ acts freely by scaling, and $Q = P(E)$ is the quotient of $E$ with respect to this action.
Therefore, we have the $\mathbb{R}^{*}$-principal bundle $\pi : E \to Q$.
Also we have the induced action of $\mathbb{R}^{*}$ on the total space of the linear frame bundle $GL(E)$, and the quotient space is $PGL(Q)$.
The quotient map $GL(E) \to PGL(Q)$ is $\mathbb{R}^{*}$-principal bundle.
If $E$ is an orientable vector bundle of rank $n + 1$, where $n$ is odd, then the structure group $GL(n + 1)$ of $GL(E)$ reduces to $SL(n + 1)$, and in this case we have the double covering $SL(E) \to PGL(Q)$.
For an orientable vector bundle $E$ of rank $n + 1$, one can take a metric $g$ on $E$, therefore the $GL(n + 1)$-principal bundle $GL(E)$ of linear frames reduces to a $SO(n + 1)$-principal bundle of positively oriented orthonormal frames $SO(E)$.
Therefore, for $Q = P(E)$, the bundle $PGL(Q)$ reduces to the subgroup $SO(n + 1)/{\pm I} \subset PGL(n) = SL(n + 1)/{\pm I}$.
\label{ex:6}
\end{ex}

Therefore, any connection in $GL(E)$ determines a unique connection in $PGL(E)$~\cite{kobayashi_nomizu1963}(Chapter II, Proposition 1).
\begin{stat}
Two linear connections $\nabla$ and $\nabla'$ in the vector bundle $E$ induce the same projective connection in $P(E)$ if and only if the deformation tensor $T = \nabla' - \nabla$ has the form
\begin{equation}
T_i{}^a_b = \xi_i \delta^a_b.
\label{eq:62}
\end{equation}
\label{stat:7}
\end{stat}
If $Q = P(E)$, where $E$ is an oriented vector bundle, then for any projective connection in $Q$ we can find an equi-affine connection $\nabla$ in $E$ with respect to a given volume form $\theta \in \Omega^{n + 1}E$, i.\,e. $\nabla \theta = 0$, such that $\nabla$ induces the given connection in $Q$.
Indeed in this case $SL(E, \theta)$ covers $PGL(Q) = SL(E, \theta)/\mathbb{Z}_2$, $\mathbb{Z}_2 = {\pm I}$, and any connection in $PGL(P(E))$ lifts to a connection in $SL(E, \theta)$.
\begin{stat}
Let $E$ be an oriented vector bundle, and $\theta \in \Omega^{n + 1}E$ be a volume form in $E$.
Then there is one-to-one correspondence between equi-affine connections on $E$ with respect to $\theta$ and the projective connections in $P(E)$.
\label{stat:8}
\end{stat}
\begin{rem}
In terms of parallel translation this correspondence can be explained as follows.
Let $\Gamma$ be a projective connection in $Q = P(E)$ induced by a linear connection $\nabla$ in $E$.
In terms of the parallel translation this means that a section $L$ of $Q$ along $\gamma$ is parallel with respect to the connection $\Gamma$ if there exists a section $s$ of $E$ along $\gamma$ which is parallel with respect to $\nabla$ and generates $L$.
This can be expressed also in terms of covariant derivative: $L = [ s ]$ is parallel with respect to $\Gamma$ if and only if $\nabla_{\dot\gamma} s = \mu s$.
Now any projective frame field $\mathcal{L} = \left\{ L_0, L_1, \cdots, L_n \right\}$ in $Q = P(E)$ determines a frame field $\mathcal{E} = \left\{E_1, \cdots, E_n\right\}$ in $E$ such that $L_i = [ E_i ]$, and $L_0 = [ E_0 ]$, where $E_0 = E_1 + E_2 + \cdots + E_n$, up to a scaling.
If in addition we have a volume form $\theta$, the projective frame field determines the linear frame field $\left\{ E_i \right\}$ up to a sign.
Then $\nabla_{\dot\gamma} E_i = \mu_i E_i$ and $\nabla_{\dot\gamma} E_0 = \mu_0 E_0$, hence follows that $\mu_0 = \mu_1 = \cdots = \mu_n$.
If we assume that the linear connection $\nabla$ is equi-affine with respect to a volume form $\theta$, then $\nabla \theta = 0$ and the function $\mu_0 = \frac{d}{dt} \log \theta(E_1, \cdots, E_n)$.
\label{rem:8}
\end{rem}
\subsection{Section of projective bundle and reduction of the bundle of projective frames}
\label{subsec:4_3}
\begin{stat}
Let $Q$ be a projective bundle of rank $1$.
Let $Aff(1) \subset PGL(1)$ be the subgroup of affine transformations of line.
Then $Q \cong PGL(Q)/Aff(1)$ and a section of projective bundle $Q$ is equivalent to the reduction of the bundle $PGL(Q)$ to the subgroup $Aff(1)$.
\label{stat:9}
\end{stat}
\begin{proof}
This follows from the fact that the group $PGL(1)$ acts transitively on $\mathbb{R}P^1$, and the isotropy subgroup of a point in $\mathbb{R}P^1$ is the group $Aff(1)$.
\end{proof}

Therefore, $\bar\alpha$ is a generator of $H^1(\mathbb{R}P^1)$.
Now let us take a projective connection $H$ is $Q$ which is determined by an equi-affine connection $\hat H$ in $E$.
Now we can construct the form $\alpha$ in $\Omega^1(Q)$ such that $\left.\alpha\right|_H = 0$, $d i_x \alpha = 0$, and $i_x^*\alpha$ represents the class $[\bar \alpha] \in H^1(\mathbb{R}P^1)$.
Let us take a metric $g$ in $E$, the volume form $\theta$ associated with $g$, and let $\omega$ be the connection form on $E$, that is the projection onto the vertical subspace parallel to $\hat H$.
Now let us consider the $1$-form
\begin{equation}
\hat\alpha_v(X) = \frac{1}{2 g(v, v)}\theta(\omega(X), v) \in \Omega^1(E_0),
\label{eq:64}
\end{equation}
where $v \in E$, $E_0 = E \setminus 0(M)$, and $0$ is the zero section of $E$.
This form $\hat\alpha$ vanishes on $H$, and the metric $g$ allows us to choose the trivialization of the bundle $E$ such that the maps $i_x$ are isomorphisms of the euclidean vector spaces $(E_x, g_x)$ and $\mathbb{R}^n$ with the standard metric.
Therefore by $i_x$ the form $\hat\alpha$ restricted to the fibers is sent to the form~\eqref{eq:63}.
Now let us consider local coordinate system $(x^i, y^a)$ on $E$ such that $g = (y^1)^2 + (y^2)^2$, then $\theta = -y^2 dy^1 + y^1 dy^2$.
Consider the local coframe $dx^i$, $Dy^a = dy^a + \Gamma_i{ }^a_b y^b dx^i$.
\begin{lm}
\begin{equation}
d(Dy^a) = \Gamma_i{ }^a_b Dy^b \wedge dx^i + R_{ij}{ }^a_b y^b dx^i \wedge dx^j,
\label{eq:65}
\end{equation}
where $R_{ij}{ }^a_b = \partial_i \Gamma_j{ }^a_b - \partial_j \Gamma_i{ }^a_b + \Gamma_i{ }^a_c \Gamma_j{}^c_b - \Gamma_j{ }^a_c \Gamma_i{}^c_b$ is the curvature tensor of the linear connection in $E$.
\label{lm:2}
\end{lm}
\begin{proof}
We have
\begin{multline}
d(Dy^a) =d( dy^a + \Gamma_i{ }^a_b y^b dx^i ) =d\Gamma_i{ }^a_b y^b \wedge dx^i + \Gamma_i{ }^a_b dy^b \wedge dx^i =
\\
\partial_j\Gamma_i{ }^a_b y^b dx^j \wedge dx^i + \Gamma_i{ }^a_b (Dy^b - \Gamma_j{}^b_c y^c dx^j) \wedge dx^i =
\\
\Gamma_i{ }^a_b Dy^b \wedge dx^i +
\left(\partial_j\Gamma_i{ }^a_b y^b dx^j \wedge dx^i - \Gamma_i{ }^a_b \Gamma_j{}^b_c y^c dx^j \wedge dx^i \right) =
\\
\Gamma_i{ }^a_b Dy^b \wedge dx^i +
\left(\partial_j\Gamma_i{ }^a_b y^b dx^j \wedge dx^i + \Gamma_j{ }^a_b \Gamma_i{}^b_c y^c dx^j \wedge dx^i \right) =
\\
\Gamma_i{ }^a_b Dy^b \wedge dx^i + R_{ij}{ }^a_b y^b dx^i \wedge dx^j.
\label{eq:66}
\end{multline}
\end{proof}
The form $\hat{\alpha}$ is written with respect to this frame as follows:
\begin{equation}
\hat{\alpha} = \frac{1}{2}\frac{1}{(y^1)^2 + (y^2)^2} \left( -y^2 Dy^1 + y^1 Dy^2 \right).
\label{eq:67}
\end{equation}
Now let us assume that the connection is adapted to the metric $g$ in $E$, in this case
$\Gamma_i{}^a_b = -\Gamma_i{}^b_a$.
Then we have
\begin{equation}
d ((y^1)^2 + (y^2)^2 ) = 2 \left( y^1 Dy^1 + y^2 Dy^2 \right),
\label{eq:68}
\end{equation}
because
\begin{multline}
d ((y^1)^2 + (y^2)^2 ) =2 \left( y^1 dy^1 + y^2 dy^2 \right) =
\\
2 \left( y^1 (Dy^1 - \Gamma_i{}^1_2 y^2 dx^i) + y^2 (Dy^2 - \Gamma_i{}^2_1 y^1 dx^i) \right)
\\
= 2 \left( y^1 Dy^1 + y^2 Dy^2 \right).
\label{eq:69}
\end{multline}
Also we have that
\begin{equation}
\begin{array}{l}
dy^1 \wedge Dy^2 = Dy^1 \wedge Dy^2 - \Gamma_i{}^1_2 y^2 dx^i \wedge Dy^2,
\\[5pt]
y^1 d Dy^2 = \Gamma_i{}^2_1 y^1 Dy^1 \wedge dx^i + R_{ij}{ }^2_1 (y^1)^2 dx^i \wedge dx^j,
\\[5pt]
dy^2 \wedge Dy^1 = Dy^2 \wedge Dy^1 - \Gamma_i{}^2_1 y^1 dx^i \wedge Dy^1,
\\[5pt]
y^2 d Dy^1 = \Gamma_i{}^1_2 y^2 Dy^2 \wedge dx^i + R_{ij}{ }^1_2 (y^2)^2 dx^i \wedge dx^j,
\end{array}
\label{eq:70}
\end{equation}
Therefore,
\begin{multline}
d (y^1 Dy^2 - y^2 Dy^1) =
\\
\left( d y^1 \wedge Dy^2 + y^1 d D y^2 - dy^2 \wedge Dy^1 - y^2 d Dy^1 \right) =
\\
2 Dy^1 \wedge Dy^2 + R_{ij}{}^2_1 \left( (y^1)^2 + (y^2)^2 \right) dx^i \wedge dx^j.
\label{eq:71}
\end{multline}
Thus,
\begin{multline}
d \hat{\alpha} =
\\
\frac{1}{2} \left[ d\left(\frac{1}{(y^1)^2 + (y^2)^2}\right) \wedge \left( -y^2 Dy^1 + y^1 Dy^2 \right) + \frac{1}{(y^1)^2 + (y^2)^2} d\left( -y^2 Dy^1 + y^1 Dy^2 \right) \right] =
\\
- \frac{1}{((y^1)^2 +(y^2)^2)^2} \left( y^1 Dy^1 +y^2 Dy^2 \right) \wedge \left( -y^2 Dy^1 +y^1 Dy^2 \right) +
\\
+ \frac{1}{(y^1)^2 + (y^2)^2} Dy^1 \wedge Dy^2 + \frac{1}{2} R_{ij}{}^2_1 dx^i \wedge dx^j
\\
= \frac{1}{2} R_{ij}{}^2_1 dx^i \wedge dx^j.
\label{eq:72}
\end{multline}
Note that $\Omega = \pi^*(R_{ij}{}^2_1 dx^i \wedge dx^j)$ is the curvature form of the connection $H$ restricted to $\pi^{-1}(U)$, where $U$ is the coordinate neighborhood.
\begin{thm}
Let $E \to M$ be a vector bundle, $Q = P(E)$, and $j : P(E) \to Q$.
\begin{enumerate}
\item
There exist a $1$-form $\alpha \in \Omega^1(Q)$ such that $\hat{\alpha} = j^* \alpha$.
\item
$\left.\alpha\right|_H = 0$
\item
$d i_x \alpha = 0$, and $i_x^*\alpha$ represents the class $[\bar \alpha] \in H^1(\mathbb{R}P^1)$.
\item
$d\alpha = \frac{1}{2} \pi^*(\Omega)$.
\end{enumerate}
\label{thm:3}
\end{thm}
\begin{cor}
Let $E \to M$ be a vector bundle and $Q = P(E)$.
Assume that $g$ is a metric in $E$.
Let $\Omega$ be the curvature form of the connection in $Q$ induced by a connection in $E$ adapted to $g$.
Let $a \in H^1(\mathbb{R}P^1)$ is represented by the form $\bar \alpha$.
If $s : M \setminus \Sigma \to Q$ is a section with singularities,
\begin{equation}
ind (s; a) = \int_M \Omega.
\label{eq:73}
\end{equation}
\label{cor:3}
\end{cor}

It is clear that on $M \setminus \Sigma$ the bundle $L(M)$ reduces to the principal $GL(n-1)$-subbundle consisting of frames with the first vector equal to the value of $X$ at the corresponding point.
\label{ex:7}
\end{ex}

Thus, by assuming the existence of the $2$-dimensional oriented compact manifold $S$ and the map $q:S\rightarrow E$ satisfying the properties given in Section~\ref{sec:1}, by Theorem~\ref{thm:2}, we obtain the following equality
\begin{equation}
\int_S(q^{*}L_X\alpha +\frac{1}{2}q^{*}\tilde{\alpha}([\omega_E, \omega_E]))=\sum_{i=\overline{1, k}} index_{x_i}(s,a),
\label{eq:86}
\end{equation}
where $s:M\setminus\Sigma \rightarrow E$ is the section corresponding to the reduction of $\bar{P}|_{M\setminus \Sigma}$ to $G$. The result given by the equation~\eqref{eq:86} will be called \emph{the Hopf-Gauss-Bonnet theorem for principal $G$-bundle with singularities}.

Therefore, we can choose this generator to construct the form $\alpha\in \Omega^{1}(SO(M))$, and the connection form on $SO(M)$ induced by the Levi-Civita connection.
This connection form is given by equation~\eqref{eq:42}.
Thus, if $S$ and $q: S \rightarrow T^{1}M$ are the manifold and the map, respectively, constructed in section~\ref{sec:4}, the equation~\eqref{eq:86} reduces to the equation~\eqref{eq:46}.  
Hence, Hopf-Gauss-Bonnet theorem in principal $G$-bundle with singularities is a generalization of the classical Gauss-Bonnet theorem.
\label{rem:10}
\end{rem}

Thus, the expression at the right side of equation~\eqref{eq:86} can be written as follows
\begin{equation}
\sum_{x_i \in \Sigma} index_{x_i}(s,a)=\sum_{x_i \in \Sigma} \sum_{j=\overline{1, k}}ind_{x_i}(s_j, [d\phi_j]).
\label{eq:91}
\end{equation}
Furthermore, $d\overset{i}{G}=K_i \theta$, and $d\alpha =\sum_{j=\overline{1, k}} \pi^{*}(K_i \theta)$.
Therefore, the expression at the left side of equation~\eqref{eq:86} reduces to the following equality
\begin{equation}
\int_S q^{*}\pi^{*}dG=\sum_{j=\overline{1, k}}\int_M K_i \theta
\label{eq:92}
\end{equation}
Hence, we obtain the following equation
\begin{equation}
\sum_{i=\overline{1, k}}\int_M K_i \theta = \sum_{x_i \in \Sigma} \sum_{j=\overline{1, k}}ind_{x_i}(s_j, [d\phi_j]).
\label{eq:93}
\end{equation}
\end{proof}

$G$-structures with singularities
\label{subsec:5_1}
\begin{df}
Let $\bar{G}$ be a Lie group, and $G\subset \bar{G}$ be a Lie subgroup of $G$.
Let $M$ be a manifold, and $\Sigma$ be a submanifold of $M$.
A principal $\bar{G}$-bundle $\bar{P}(M, \bar{G})$ is called a \emph{principal $G$-bundle with singularities $\Sigma$} if the structure group $\bar{G}$ of $\bar{P}|_{M\setminus \Sigma}$ reduces to $G$.
\label{df:5}
\end{df}
\begin{ex}
Let $X$ be a vector field on a manifold $M$ with a discrete set of zeros $\Sigma \subset M$.
Then the frame bundle $L(M)$ is a principal $GL(n-1)$-bundle with singularities on $M$.
It is clear that on $M \setminus \Sigma$ the bundle $L(M)$ reduces to the principal $GL(n-1)$-subbundle consisting of frames with the first vector equal to the value of $X$ at the corresponding point.
\label{ex:7}
\end{ex}

\begin{ex}
If $M$ is a two-dimensional oriented Riemannian manifold, and $X$ is a vector field on $M$ with a discrete set of zeros $\Sigma \subset M$, then the orthonormal frame bundle $SO(M)$ is a principal $\{e\}$-bundle with singularities where the set of singularities $\Sigma$ because the vector field induced trivialization of $SO(M)$ over $M \setminus \Sigma$.
\label{ex:8}
\end{ex}
\begin{ex}
Let $M$ be a Riemannian manifold of dimension $n$. The principal $GL(n)$-bundle of frames $L(M)$ is a principal $O(n)$-bundle with an empty set of singularities.
\label{ex:9}
\end{ex}
Let us recall that there is an important relation between $H$-reductions of a principal $G$-bundle $P \to M$ and sections of the fiber bundle $P/H \to M$ which is given by the following statement.
\begin{stat}[\cite{kobayashi_nomizu1963}(Chapter I, Proposition 5.6)]
Let $P$ be a $G$-principal bundle and let $H$ be a Lie subgroup of $G$.
Then $G$ has a reduction to a principal $H$-bundle if and only if the associated bundle $P/H\rightarrow M$ admits a section.In particular, if $H=\{e\}$ then $P$ has a section.
\label{stat:10}
\end{stat}
\begin{cor}
Let $\bar{P}(M, \bar{G}, \pi)$ a principal $G$-bundle with singularities, and let $\Sigma$ be the set of singularities.
Then there is a section $s: M\setminus \Sigma \rightarrow \bar{P}/G$.
\label{cor:4}
\end{cor}

In what follows by $\mathfrak{\bar{g}}$ we denote the Lie algebra of $\bar{G}$, and by $\mathfrak{g}$ the Lie algebra of $G$.
Moreover, we suppose that the Lie group $\bar{G}$ is compact and connected.
Then $G$ is also compact and the quotient $\bar{G}/G$ is reductive, i.\,e, $\mathfrak{\bar{g}}$ has an $ad(G)$-invariant decomposition $\bar{\mathfrak{g}}=\mathfrak{g}\oplus \mathfrak{m}$.


Let $M$ be a $2$-dimensional compact connected oriented manifold.
Let $\bar{P}(M, \bar{G}, \bar{\pi})$ be a principal $G$-bundle with singularities, where the set of singularities $\Sigma$ consists of isolated points.
Consider the fiber bundle $\pi_E: E = \bar{P}/G \rightarrow M$.
Recall that the canonical projection $\pi_G: \bar{P}\rightarrow E=\bar{P}/G$ is a principal $G$-bundle~\cite{kobayashi_nomizu1963}(Chapter I, Proposition 5.5), and $\pi_G$ is a fiber bundle morphism: 
\begin{equation}
\xymatrix{
\bar{P} \ar[rr]^{\pi_G} \ar[rd]_{\pi} & & E = \bar{P}/G \ar[ld]^{\pi_E}
\\
&M &
}
\label{eq:74}
\end{equation}

Assume that $\bar{P}$ is endowed with a connection form $\bar{\omega}: T\bar{P} \rightarrow \bar{\mathfrak{g}}$, and let
$\bar{H} = \ker\bar{\omega}$ be the horizontal distribution of the connection, and $\bar{V}=\ker d\pi$ the vertical distribution on $\bar{P}$.
Note that $\bar{H}$ and $\bar{V}$ are vector subbundles of $T\bar{P}$, and $T\bar{P}=\bar{H} \oplus \bar{V}$.

Define the operator field $\widetilde{\omega} : T\bar{P} \to \bar{V}$ as follows:
\begin{equation}
\widetilde{\omega}_{\bar{p}}(\bar{X}) = \sigma_{\bar{p}}(\bar{\omega}_{\bar{p}}(\bar{X})),
\label{eq:75}
\end{equation}
where $\bar{X} \in T_{\bar{p}} \bar{P}$, and $\sigma_{\bar{p}}(\bar{a})$, $\bar{a} \in \bar{g}$, is the value of the fundamental vector field $\sigma(\bar{a})$ at the point $\bar{p}$.

\begin{lm}
a) $\widetilde{\omega}$ is a field of projectors onto the vertical distribution $\bar{V}$ with kernel $\bar{H}$.

b) $\widetilde{\omega}_{\bar{p}\bar{g}} \circ dR_{\bar{g}} (\bar{X}) = dR_{\bar{g}} \circ \widetilde{\omega}_{\bar{p}} (\bar{X})$, where $R_{\bar{g}} : \bar{G} \to \bar{G}$, $R_{\bar{g}} \bar{g}' = \bar{g}' \bar{g}$.

\label{lm:3}
\end{lm}
\begin{proof}
It is clear that $\widetilde{\omega}$ vanishes on $\bar{H}$.
For $\bar{X} \in \bar{V}_{\bar{p}}$, $\bar{p} \in \bar{P}$, one can find $\bar{a} \in \bar{\mathfrak{g}}$ such that $\sigma_{\bar{p}}(\bar{a}) = \bar{X}$.
Then, $\bar{\omega}_{\bar{p}}(\bar{X}) = \bar{a}$, hence follows that
$\widetilde{\omega}_{\bar{p}}(\bar{X}) = \sigma_{\bar{p}}(a) = X$.
Thus we get a).

Now a) implies b) because $dR_{\bar{g}} : T_{\bar{p}} \bar{P} \to T_{\bar{p}\bar{g}}\bar{P}$ is an isomorphism, which maps $\bar{H}_{\bar{p}}$ to $\bar{H}_{\bar{p}\bar{g}}$, and $\bar{V}_{\bar{p}}$ to $\bar{V}_{\bar{p}\bar{g}}$.
\end{proof}

\begin{stat}
a) There exists a operator field $\omega_E$ on $E$ such that, for each $\bar{p} \in \bar{P}$, the following diagram is commutative:
\begin{equation}
\xymatrix{
T_{\bar{p}} \bar{P} \ar[r]^{\widetilde{\omega}} \ar[d]_{d\pi_G} & \bar{V}_{\bar{p}} \ar[d]^{d\pi_G}
\\
T_{\pi_G(p)} E \ar[r]^{\omega_E} & VE_{\pi_G(p)}
}
\label{eq:76}
\end{equation}

b) $\omega_E$ is a projector onto $VE$ with kernel $HE = \ker\omega_E = d\pi_G(\bar{H})$.

c) The decomposition $T\bar{P}= \bar{H} \oplus \bar{V}$ of $T\bar{P}$ projects onto a decomposition $TE=HE\oplus VE$ of $TE$ via $d\pi_G$.
\label{stat:11}
\end{stat}
\begin{proof}
a) If $d\pi_G(\bar{X}_{\bar{p}}) = d\pi_G(\bar{X}'_{\bar{p'}})$, then $\bar{p}' = \bar{p} g$, and $\bar{X}' = dR_g \bar{X} + \bar{Y}$, where $g \in G$ and $\bar{Y} = \sigma_{\bar{p} g}(a) \in \ker d\pi_G$ with $a \in \mathfrak{g}$.
By Lemma~\ref{lm:3}, we have
\begin{equation}
\widetilde{\omega}_{\bar{p} g}(\bar{X}') =\widetilde{\omega}_{\bar{p} g}(dR_g \bar{X} + \sigma_{\bar{p} g}(a)) =
\widetilde{\omega}_{\bar{p} g}(dR_g \bar{X}) + \sigma_{\bar{p} g}(a) =
dR_g (\widetilde{\omega}_{\bar{p}}(X) + \sigma_{\bar{p} g}(a).
\label{eq:77}
\end{equation}
Then,
\begin{equation}
d\pi_G(\widetilde{\omega}_{\bar{p}}(\bar{X})) = d\pi_G(\widetilde{\omega}_{\bar{p}'}(\bar{X}')),
\label{eq:78}
\end{equation}
this proves that $\omega_E$ in the diagram~\eqref{eq:76} is well defined.

b) From the diagram~\eqref{eq:76} it follows that $d\pi_G(\bar{H}) \subset HE$.
For any $X \in HE_{\pi_G(\bar{p})}$, take $\bar{X} \in T_{\pi_G(\bar{p})} \bar{P}$ such that $d\pi_G(\bar{X}) = X$.
Then $d\pi_G(\widetilde{\omega}(\bar{X})) = 0$, this means that $\widetilde{\omega}(\bar{X}) = \sigma_{\bar{p}}(a)$, where $a \in \mathfrak{g}$.
