d\alpha=L_X\alpha+1/2\tilde{\alpha}([\omega_E, \omega_E]).
\label{eq:85}
\end{equation}
Thus, by assuming the existence of the $2$-dimensional oriented compact manifold $S$ and the map $q:S\rightarrow E$ satisfying the properties given in Section~\ref{sec:1}, by Theorem~\ref{thm:2}, we obtain the following equality
\begin{equation}
\int_S(q^{*}L_X\alpha +\frac{1}{2}q^{*}\tilde{\alpha}([\omega_E, \omega_E]))=\sum_{i=\overline{1, k}} index_{x_i}(s,a),
\label{eq:86}
\end{equation}
