\begin{df}
Let $Q \to M$ be a projective bundle of rank $n$.
The principal bundle $PGL(Q)$ with the group $PGL(n)$ adjoint to $Q$ is called the \emph{bundle of projective frames}.
\label{df:4}
\end{df}
\begin{ex}
On the total space of a vector bundle $E \to M$ the group $\mathbb{R}^{*} = \mathbb{R} \setminus \left\{ 0 \right\}$ acts freely by scaling, and $Q = P(E)$ is the quotient of $E$ with respect to this action.
Therefore, we have the $\mathbb{R}^{*}$-principal bundle $\pi : E \to Q$.
Also we have the induced action of $\mathbb{R}^{*}$ on the total space of the linear frame bundle $GL(E)$, and the quotient space is $PGL(Q)$.
The quotient map $GL(E) \to PGL(Q)$ is $\mathbb{R}^{*}$-principal bundle.
If $E$ is an orientable vector bundle of rank $n + 1$, where $n$ is odd, then the structure group $GL(n + 1)$ of $GL(E)$ reduces to $SL(n + 1)$, and in this case we have the double covering $SL(E) \to PGL(Q)$.
For an orientable vector bundle $E$ of rank $n + 1$, one can take a metric $g$ on $E$, therefore the $GL(n + 1)$-principal bundle $GL(E)$ of linear frames reduces to a $SO(n + 1)$-principal bundle of positively oriented orthonormal frames $SO(E)$.
Therefore, for $Q = P(E)$, the bundle $PGL(Q)$ reduces to the subgroup $SO(n + 1)/{\pm I} \subset PGL(n) = SL(n + 1)/{\pm I}$.
\label{ex:6}
\end{ex}

\begin{proof}
For $X \in H$, $\omega_E(X) = 0$, therefore $\alpha(X) = 0$.

Recall that the trivializations of $E = P/G$ are constructed in the following way.
For a good covering $U_i$ of $M$ we take sections $s_i : U_i \to P$, then we define the charts
\begin{equation}
\psi_i : U_i \times \bar{G}/G \to \pi_E^{-1}(U_i), \quad (x, [\bar{g}]) \to [s_i(x) \bar{g}] = \pi_G(s_i(x) \bar{g}).
\label{eq:82}
\end{equation}
Therefore, for $x \in U_i$, $\eta_x^{-1} : \bar{G}/G \to E_x = \pi_E^{-1}(x)$, $\eta_x^{-1}[\bar{g}] = \pi_G(s_i(x)\bar{g})$.

Now let us fix $x \in U_i \subset M$ and let $\bar{p} = s_i(x)$.
For any $y \in E_x$ and $Y \in V_yE$, we have that $y = \pi_G(\bar{p} \bar{g}) = [\bar{p}, \bar{g}] = \eta_x^{-1}(\bar{g})$ and $Y = d\pi_G(\sigma_{\bar{p} \bar{g}}(a)) = [\bar{p} \bar{g}, a] = d\eta_x^{-1} (dL_{\bar{g}} a)$, where $a \in \mathfrak{m}$, and $L_{\bar{g}} : \bar{G}/G \to \bar{G}/G$, $L_{\bar{g}} \bar{g}' = \bar{g}\bar{g}'$.
Note that here we use the isomorphism constructed in Lemma~\ref{lm:4}. 
Then
\begin{equation}
\alpha(Y) = \widetilde{\alpha}(\omega_E(Y)) = \widetilde{\alpha}(Y) = \xi_0(a) = \xi(dL_{\bar{g}} a).
\label{eq:83}
\end{equation}
Therefore $\alpha(d\eta_x^{-1} (dL_{\bar{g}} a) ) = \xi(dL_{\bar{g}} a)$, thus $(\eta_x^{-1})^* \left.\alpha\right|_{E_x} = \xi$, then $\eta_x^* \xi = \left.\alpha\right|_{E_x}$.

Thus $d\left(\left.\alpha\right|_{E_x} \right) = 0$, and $\left[\left.\alpha\right|_{E_x} \right] = H^1(\eta_x) a$.
\end{proof}

The curvature form $\Omega_E= D\omega_E$ of the connection $\omega_E$ (see Section~\ref{sec:3}, equation~\eqref{eq:25}) can be represented by the following equality:
\begin{equation}
\Omega_E=1/2[\omega_E, \omega_E],
\label{eq:84}
\end{equation}
where $[ \ , \ ]: \Omega^{k}(E, TE)\times \Omega^{l}(E, TE)\rightarrow \Omega^{k+l}(E, TE)$ is the Frolicher-Nijenhuis bracket~\cite{michor2000}(Chapter IV, section 16.3).
In particular, for $1$-forms $\omega_1$ and $\omega_2$ this bracket is given by the following equation
\begin{align*}
[w_1, w_2](X, Y)&=[\omega_1(X), \omega_2(Y)]-[\omega_1(Y), \omega_2(X)]-\omega_2([\omega_1(X), Y])\-\\& \omega_1([\omega_2(X), Y])-[\omega_1(Y),X]-[\omega_2(Y), X]+(\omega_1 \circ \omega_2+\omega_2 \circ \omega_1)[X,Y].
\end{align*}

We repeat the arguments of subsection~\ref{subsec:3_4} and get that
\begin{equation}
d\alpha=L_X\alpha+1/2\tilde{\alpha}([\omega_E, \omega_E]).
\label{eq:85}
\end{equation}
Thus, by assuming the existence of the $2$-dimensional oriented compact manifold $S$ and the map $q:S\rightarrow E$ satisfying the properties given in Section~\ref{sec:1}, by Theorem~\ref{thm:2}, we obtain the following equality
\begin{equation}
\int_S(q^{*}L_X\alpha +\frac{1}{2}q^{*}\tilde{\alpha}([\omega_E, \omega_E]))=\sum_{i=\overline{1, k}} index_{x_i}(s,a),
\label{eq:86}
\end{equation}
where $s:M\setminus\Sigma \rightarrow E$ is the section corresponding to the reduction of $\bar{P}|_{M\setminus \Sigma}$ to $G$. The result given by the equation~\eqref{eq:86} will be called \emph{the Hopf-Gauss-Bonnet theorem for principal $G$-bundle with singularities}.


\begin{rem}
If $X$ is a vector field on $M$, and $\Sigma$ is the set of zeros of $X$, then $Y=\frac{X}{|X|}$ defines a section of the unit tangent bundle $M\rightarrow T^{1}M$ over $M\setminus \Sigma$.
Since $T^{1}M$ is the associated bundle to the bundle of orthonormal frames $M\rightarrow SO(M)$ with respect of standard action of $SO(2)$ on $\mathbb{S}^{1}$, then $SO(M)|_{M\setminus \Sigma}$ reduces to the trivial subgroup $G=\{e \}$ of $\bar{G}=SO(2)$.
Now, $\bar{G}/G=SO(2)$, and $SO(2)$ is diffeomorphic to $\mathbb{S}^{1}$, then $H^{1}(\bar{G}/G)$ is $1$-dimensional vector space generated by the angle form on $\mathbb{S}^{1}$.
Therefore, we can choose this generator to construct the form $\alpha\in \Omega^{1}(SO(M))$, and the connection form on $SO(M)$ induced by the Levi-Civita connection.
This connection form is given by equation~\eqref{eq:42}.
Thus, if $S$ and $q: S \rightarrow T^{1}M$ are the manifold and the map, respectively, constructed in section~\ref{sec:4}, the equation~\eqref{eq:86} reduces to the equation~\eqref{eq:46}.  
Hence, Hopf-Gauss-Bonnet theorem in principal $G$-bundle with singularities is a generalization of the classical Gauss-Bonnet theorem.
\label{rem:10}
\end{rem}

\begin{proof}
Let $S$ be an oriented $2$-manifold with boundary, and let $q: S \rightarrow E$ a map which satisfies the condition given in section~\ref{sec:1}, that is, $q_i$ restricted to $\overset{\circ}{S} = S \setminus \partial S$ is a diffeomorphism between $S \setminus \partial S$ and $s_i(M \setminus \Sigma)$.
Now, because $E=\tilde{E}_1 \times \cdots \tilde{E}_k$, $q$ has the form $q=(q_1, \cdots, q_k)$, and for each $i$, the map $q_i: S\rightarrow \tilde{E}_i$ also satisfies this condition.
This fact follows from the commutative diagram
\begin{equation}
\xymatrix{
& M\setminus \Sigma \ar[r]^{id} \ar[d]_{s} & M\setminus \Sigma \ar[d]^{s_i}\\
\overset{\circ}{S}\ar[r]^{q} & s(M\setminus \Sigma)\ar[r]^{\tilde{p}_i} & s_i(M\setminus \Sigma)
}
\label{eq:90}
\end{equation}
Since the vertical arrows are diffeomorphisms, we have that $q_i$ is a diffeomorphism.
Therefore, for each $i = 1,\cdots, k$, the map $q_i=\tilde{p}_i\circ q$ is also a diffeomorphism.


Let us take the cohomology class $a=[(d\phi_1, \cdots, d\phi_k)]$ of the fiber of $\tilde{E}$, where $d\phi_i$ is the angular form on the fiber $F_i$ of $E_i$, then $a=[d\phi_1]+ \cdots +[d\phi_k]$.
Thus, the expression at the right side of equation~\eqref{eq:86} can be written as follows
\begin{equation}
\sum_{x_i \in \Sigma} index_{x_i}(s,a)=\sum_{x_i \in \Sigma} \sum_{j=\overline{1, k}}ind_{x_i}(s_j, [d\phi_j]).
\label{eq:91}
\end{equation}
Furthermore, $d\overset{i}{G}=K_i \theta$, and $d\alpha =\sum_{j=\overline{1, k}} \pi^{*}(K_i \theta)$.
Therefore, the expression at the left side of equation~\eqref{eq:86} reduces to the following equality
\begin{equation}
\int_S q^{*}\pi^{*}dG=\sum_{j=\overline{1, k}}\int_M K_i \theta
\label{eq:92}
\end{equation}
Hence, we obtain the following equation
\begin{equation}
\sum_{i=\overline{1, k}}\int_M K_i \theta = \sum_{x_i \in \Sigma} \sum_{j=\overline{1, k}}ind_{x_i}(s_j, [d\phi_j]).
\label{eq:93}
\end{equation}
\end{proof}

\begin{rem}
Note that if $\Sigma_i \cap \Sigma_j$ is non empty, and $x\in \Sigma_i \cap \Sigma_j$, then the indexes $ind_x(s_i)$ and $ind_x(s_j)$ could be different, still in the case where the vector bundles $E_i$ and $E_j$ are the same.
\label{rem:11}
\end{rem}

