\begin{df}
A \emph{projective bundle} is a locally trivial bundle $Q \to M$ with typical fiber $\mathbb{R}P^n$ and structure group $PGL(n)$.
The number $n$ is called the \emph{rank} of $Q$.
\label{df:3}
\end{df}
\begin{ex}
Let $E \to M$ be a vector bundle.
Then the bundle $P(E)$ of $1$-dimensional subspaces of the fibers of $E$ is called the \emph{projectivization} of $E$ and it is projective bundle.
\label{ex:4}
\end{ex}

If we have a projective bundle $Q \to M$, then can we find a vector bundle $E$ such that $Q = P(E)$?
Note that for $A \in GL(n + 1)$, we have $\det (\lambda A) = \lambda^{n + 1} \det A$.
Now for an even $n$, the group $PGL(n) = GL(n + 1)/{A \sim \lambda A}$, $\lambda \in \mathbb{R}$, is isomorphic to $SL(n + 1)$ because for each equivalence class $[A] \in PGL(n)$ one can find a representative $B = (\det A)^{-1/(n + 1)} A \in [ A ]$ such that $\det B = 1$.
This $B$ is unique because for $B, B' \in [A]$ such that $\det B = \det B' = 1$, we have that $B' = \lambda B$ and $\lambda^{n + 1} = 1$, this implies that $\lambda = 1$.
Therefore in this case $PGL(n) \cong SL(n + 1)$.
For an odd $n$, the group $PGL(n) = PGL_{+}(n) \sqcup PGL_{-}(n)$, where
\begin{equation}
PGL_{+}(n) = \left\{ [ A ] \mid \det A > 0 \right\},
\quad
PGL_{-}(n) = \left\{ [ A ] \mid \det A < 0 \right\}.
\label{eq:47}
\end{equation}
By the same arguments as for case of even $n$ we get that $PGL_{+}(n) \cong SL(n)/{\pm I}$.
Note that $PGL_{-}(n)$ is diffeomorphic to $PGL_{+}(n)$.
If the structure group $PGL(n)$ of a projective bundle $Q$ reduces to $PGL_{+}(n)$, then $Q$ is called \emph{orientable}, on the contrary $Q$ is called \emph{no orientable}.
\begin{ex}
If a vector bundle $E$ is no orientable, then $P(E)$ is no orientable.
\label{ex:5}
\end{ex}
Now let consider the following situation.
Let $\widetilde{G}$ be a Lie group, $Z = Z(\widetilde{G})$ be the center of $\widetilde{G}$, and $G = \widetilde{G}/Z$.
So we have the exact sequence
\begin{equation}
\xymatrix{0 \ar[r] & Z \ar[r]^i &\widetilde{G} \ar[r]^p & G \ar[r] & 0.}
\label{eq:48}
\end{equation}
Let $P \to M$ be a $G$-principal bundle, $\mathcal{U} = \left\{ U_i \right\}$ be a good covering of a manifold $M$, and
$g_{ij} : U_{ij} \to M$ be the transition functions of $M$.
As the covering $\mathcal{U}$ is good, we can lift $g_{ij}$ up to $\widetilde{g}_{ij} : U_{ij} \to \widetilde{G}$ of $g_{ij}$, this means that the following diagram is commutative
\begin{equation}
\xymatrix{
& \widetilde{G} \ar[d]_p
\\
U_{ij} \ar[ur]^{\widetilde{g}_{ij}} \ar[r]_{g_{ij}} & G
}
\label{eq:49}
\end{equation}
Consider the Cech cochain $z = \left\{ z_{ijk} : U_{ijk} \to \widetilde{G} \right\}$ over the covering $\mathcal{U}$, where
\begin{equation}
z_{ijk} = \widetilde{g}_{ij} \widetilde{g}_{jk} \widetilde{g}_{ki}.
\label{eq:50}
\end{equation}
As $p(z_{ijk}) = g_{ij} g_{jk} g_{ki} = 1$, the functions $z_{ijk}$ take values in $Z$, therefore in fact $z \in \check{C}(\mathcal{U}; Z)$.
\begin{stat}
\begin{enumerate}
\item
The \v Cech cochain $z$ is a normalized cocycle.
\item
The \v Cech cohomology class $[ z ] \in \check{H}^2(M; Z)$ is trivial if and only if
there exists a $\widetilde{G}$-principal bundle $\widetilde{P}$ such that $P \cong \widetilde{P}/Z$.
\end{enumerate}
\label{stat:6}
\end{stat}
\begin{proof}
Let us prove that $\left\{ z_{ijk} \right\}$ is a \v Chech cocycle on $\mathcal{U}$.
First of all note that we have
\begin{equation}
\widetilde{g}_{ij} \widetilde{g}_{jk} = z_{ijk} \widetilde{g}_{ik} = \widetilde{g}_{ik} z_{ijk}.
\label{eq:51}
\end{equation}
Then
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) \widetilde{g}_{ki} = z_{ijk} \widetilde{g}_{ik} \widetilde{g}_{ki} = z_{ijk} \text{ and } \widetilde{g}_{ij} (\widetilde{g}_{jk} \widetilde{g}_{ki}) = \widetilde{g}_{ij} \widetilde{g}_{ji} z_{jki} = z_{jki},
\label{eq:52}
\end{equation}
therefore $z_{ijk} = z_{kij} = z_{jki}$.
At the same time,
\begin{equation}
z_{ijk}^{-1} \widetilde{g}_{ik}^{-1} = \left( z_{ijk} \widetilde{g}_{ik} \right)^{-1} = \left( \widetilde{g}_{ij} \widetilde{g}_{jk} \right)^{-1} = \widetilde{g}_{kj} \widetilde{g}_{ji} = z_{kji} \widetilde{g}_{ki},
\label{eq:53}
\end{equation}
hence follows that $z_{ijk}^{-1} = z_{kji} = z_{jik}$.
Moreover $z_{ijk} = 1$ if at least two indices coincide.
Thus $z = \left\{ z_{ijk} \right\}$ is a normalized cochain.
Now we have
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) (\widetilde{g}_{kj} \widetilde{g}_{jl}) = z_{ijk} \widetilde{g}_{ik} z_{kjl} \widetilde{g}_{kl} = z_{ijk} z_{kjl} z_{ikl} g_{il}
\label{eq:54}
\end{equation}
and
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) (\widetilde{g}_{kj} \widetilde{g}_{jl}) = (\widetilde{g}_{ij} (\widetilde{g}_{jk} (\widetilde{g}_{kj}) \widetilde{g}_{jl} = \widetilde{g}_{ij} \widetilde{g}_{jl} = z_{ijl} \widetilde{g}_{il},
\label{eq:55}
\end{equation}
thus $z_{ijk} z_{kjl} z_{ikl} = z_{ijl}$, this implies
\begin{equation}
\delta z = z_{jkl} z_{ikl}^{-1} z_{ijl} z_{ijk}^{-1} = 0.
\label{eq:56}
\end{equation}
If $z = \delta u$, where $u = \left\{ u_{ij} \in Z \right\}$, then
\begin{equation}
z_{ijk} = u_{ij} u_{jk} u_{ki}.
\label{eq:57}
\end{equation}
Therefore we can construct the $\widetilde{G}$-principal bundle $\widetilde{P} \to M$ with the transition functions $\widetilde{g}'_{ij} = \widetilde{g}_{ij} u_{ji}$ because
\begin{equation}
\widetilde{g}'_{ij} \widetilde{g}'_{jk} \widetilde{g}'_{ki} =\widetilde{g}_{ij} u_{ji} \widetilde{g}_{jk} u_{kj} \widetilde{g}_{ki} u_{ik} =\widetilde{g}_{ij} \widetilde{g}_{jk} \widetilde{g}_{ki} u_{ji} u_{kj} u_{ik} =
z_{ijk} u_{ji} u_{kj} u_{ik} = 1.
\label{eq:58}
\end{equation}
Now we have that $p(\widetilde{g}'_{ij}) = g_{ij}$ and from the following lemma it follows that there exists a principal bundle morphism $\pi : \widetilde{P} \to P$ written with respect to the trivializations as $(x, \widetilde{g}) \to (x, p(\widetilde{g}))$.
\begin{lm}
Let $G_a$, $a = 1, 2$ be Lie groups.
Let $\pi_a : P_a \to M$, $a = 1, 2$ be a $G_a$-principal bundle and $f : G_1 \to G_2$ be a Lie group homomorphism.
Assume that $\mathcal{U} = \left\{ U_i \right\}$ is a trivializing covering for $P_1$ and $P_2$ at the same time.
If the transition functions $g^a_{ij}$ with respect to the covering $\mathcal{U}$ are related by $f(g^1_{ij}) = g^2_{ij}$, then there exists a principal fiber bundle homomorphism $F : P_1 \to P_2$ corresponding to $f$, i.\, e. $F(p_1 g_1) = F(p_1) f(g_1)$.
\label{lm:1}
\end{lm}
\begin{proof}
We define $F_i : \pi_1^{-1}(U_i) \to \pi_2^{-1}(U_i)$ by the commutative diagram
\begin{equation}
\xymatrix{
\pi_1^{-1}(U_i) \ar[r]^{F_i} \ar[d]_{\psi_i^1} & \pi_2^{-1}(U_i) \ar[d]^{\psi_i^2}
\\
U_i \times G_1 \ar[r]^{ 1 \times f} & U_i \times G_2
}
\label{eq:59}
\end{equation}
where $\psi_a$ are the trivializations which are principal bundle isomorphisms, therefore $\psi_a(p_a g_a) = \psi_a(p_a) g_a$, where the action of $G_a$ on $U_i \times G_a$ is given by $(x, g_a) g'_a = (x, g_a g'_a)$.
From this follows that $F_i(p_1 g_1) = F_i(p_1) g_1$.
On the other hand, for $p_1 \in \pi^{-1}(U_{ij})$ we have $F_i(p_1) = F_j(p_1)$.
Indeed, we have the commutative diagram for $a = 1, 2$:
\begin{equation}
\xymatrix{
U_{ij} \times G_a{}\ar[rr]^{(x, g_a) \to (x, g^a_{ji} g_a)} & & U_{ij} \times G_a
\\
&\pi_1^{-1}(U_{ij}) \ar[lu]^{\psi^a_i} \ar[ru]_{\psi^a_j} &
}
\label{eq:60}
\end{equation}
Let $p_1 \in \pi^{-1}(U_{ij})$ and $\psi^1_i(p_1) = (x, g_1)$, then $\psi^1_j(p_1) = (x, g^1_{ji} g_1)$.
Also $\psi^2_i F_i(p_1) = (x, f(g_1))$, hence $\psi^2_j F_i(p_1) = (x, g^2_{ji} f(g_1))$.
Therefore,
\begin{equation}
\psi^2_j F_j(p_1) = (x, f(g^1_{ji} g_1)) = (x, f(g^1_{ji}) f(g_1))
= (x, g^2_{ji} f(g_1)) = \psi^2_j F_i(p_1),
\label{eq:61}
\end{equation}
thus $F_j = F_i$ on $\pi^{-1}(U_{ij})$ and therefore $\left\{ F_i \right\}$ determine a homomorphism $F : P_1 \to P_2$.
\end{proof}
From the construction of the bundle $\widetilde{P}$ it follows that $P = \widetilde{P}/Z$ and the principal fiber bundle homomorphism constructed in Lemma~\ref{lm:2} is exactly the projection $\widetilde{P} \to P=\widetilde{P}/Z$.
\end{proof}
Let $Q$ be a projective bundle of rank $n$, $n$ is odd.
Assume that $Q$ is orientable.
Let $\left\{ U_i \right\}$ be a good covering of $M$, $U_{i_1 \ldots i_k} = U_{i_1} \bigcap \cdots \bigcap U_{i_k}$, and $g_{ij} : U_{ij} \to PGL(n)$ the corresponding cocycle of transition functions.
As $U_{ij}$ are contractible, we can choose the maps $\hat{g}_{ij} : U_{ij} \to SL(n + 1)$ such that $p(\hat{g}_{ij}) = g_{ij}$, where $p : SL(n + 1) \to PGL_{+}(n)$ is the canonical projection.
Then $p(\hat{g}_{ij} \hat{g}_{jk} \hat{g}_{ki}) = g_{ij} g_{jk} g_{ki} = id \in PGL(n)$, therefore $e_{ijk} = \hat{g}_{ij} \hat{g}_{jk} \hat{g}_{ki}$ takes values in $\mathbb{Z}_2 = \left\{ \pm I \right\}$.
Note that $\mathbb{Z}_2 = \left\{ \pm I \right\}$ is the center of the group $SL(n + 1)$.
\begin{cor}
If $Q \to M$ is a projective bundle of odd rank $n$ and is oriented, then the obstruction to existence of a vector bundle $E$ such that $Q = P(E)$ is an element in $H^2(M, \mathbb{Z}_2)$.
\label{cor:2}
\end{cor}
\begin{df}
Let $Q \to M$ be a projective bundle of rank $n$.
The principal bundle $PGL(Q)$ with the group $PGL(n)$ adjoint to $Q$ is called the \emph{bundle of projective frames}.
